import { afterEach, beforeEach, expect, test, vi } from "vitest";
import { StorageService } from "../../src/util/StorageService";

beforeEach(() => {
  localStorage.clear();
  vi.spyOn(console, "log").mockImplementation(() => {});
});
afterEach(() => {
  localStorage.clear();
  vi.restoreAllMocks();
  vi.unstubAllEnvs();
  vi.resetModules();
});

// Generated by Codex and not thoroughly checked for correctness.
test.each([
  { base: "https://backend.example.test/api", expected: "https://backend.example.test/api/v1" },
  { base: "https://backend.example.test/api///", expected: "https://backend.example.test/api/v1" },
  { base: "", expected: undefined },
  { base: undefined, expected: undefined },
])("API base $base produces $expected", async ({ base, expected }) => {
  vi.resetModules();
  vi.stubEnv("VITE_BACKEND_API_URL", base);
  const { BACKEND_API_URL } = await import("../../src/util/env");
  expect(BACKEND_API_URL).toBe(expected);
});

// Generated by Codex and not thoroughly checked for correctness.
test.each([
  [undefined, false], ["false", false], ['"true"', false], ["1", false],
  ["TRUE", false], ["{}", false], ["[]", false], ["null", false], ["true", true],
] as const)("stored opt-in %s enables backend features only when it is boolean true", async (value, expected) => {
  if (value !== undefined) localStorage.setItem(StorageService.Keys.BackendEnabled, value);
  const isBackendAccessEnabled = await loadBackendAccess();
  expect(isBackendAccessEnabled()).toBe(expected);
});

// Generated by Codex and not thoroughly checked for correctness.
test.each([
  { available: "false", url: "https://backend.example.test/api" },
  { available: "true", url: "" },
])("opt-in cannot enable an unavailable backend: $available, $url", async ({ available, url }) => {
  StorageService.saveValue(StorageService.Keys.BackendEnabled, true);
  const isBackendAccessEnabled = await loadBackendAccess(available, url);
  expect(isBackendAccessEnabled()).toBe(false);
});

// Generated by Codex and not thoroughly checked for correctness.
test("unavailable local storage leaves the backend disabled", async () => {
  const isBackendAccessEnabled = await loadBackendAccess();
  vi.spyOn(Storage.prototype, "getItem").mockImplementation(() => { throw new DOMException("Unavailable", "SecurityError"); });
  expect(isBackendAccessEnabled()).toBe(false);
});

// Generated by Codex and not thoroughly checked for correctness.
test("an opt-in survives reinitialization and is never overwritten by access checks", async () => {
  StorageService.saveValue(StorageService.Keys.BackendEnabled, true);
  expect((await loadBackendAccess())()).toBe(true);
  expect((await loadBackendAccess())()).toBe(true);
  expect(localStorage.getItem(StorageService.Keys.BackendEnabled)).toBe("true");
});

async function loadBackendAccess(available = "true", url: string | undefined = "https://backend.example.test/api") {
  vi.resetModules();
  vi.stubEnv("VITE_IS_BACKEND_AVAILABLE", available);
  vi.stubEnv("VITE_BACKEND_API_URL", url);
  return (await import("../../src/util/backendAccess")).isBackendAccessEnabled;
}
